        if (sim_cur > sim_best && sim_cur > slot_prompt_similarity) {
            sim_best = sim_cur;
            ret = &slot;
        }
    }

    // if we'd lose a large portion of existing context, save it to cache first
    if (ret && f_keep < 0.5f) {
