    n_tokens_start > slot.prompt.checkpoints.back().n_tokens + params_base.checkpoint_min_step);

if (do_checkpoint) {
    create_checkpoint(slot, n_tokens_cur, pos_min, pos_max);
}
```

**Checkpoint creation:**
```cpp
// server-context.cpp:2694-2712
void create_checkpoint(server_slot & slot, int64_t n_tokens, llama_pos pos_min, llama_pos pos_max) {
    auto & ckpt = slot.spec_ckpt;

    ckpt.update_pos(n_tokens, pos_min, pos_max);
    ckpt.update_tgt(ctx_tgt, slot.id, LLAMA_STATE_SEQ_FLAGS_PARTIAL_ONLY);
    if (use_ckpt_dft) {
        ckpt.update_dft(ctx_dft.get(), slot.id, LLAMA_STATE_SEQ_FLAGS_PARTIAL_ONLY);
    }
    slot.prompt.checkpoints.push_back(std::move(ckpt));
}
```

**Checkpoint search during draft rejection:**
```cpp
// server-context.cpp:2975-3010
// search for a context checkpoint
auto it = std::find_if(
    slot.prompt.checkpoints.rbegin(),
    slot.prompt.checkpoints.rend(),
    [&](const common_prompt_checkpoint & ckpt) {
        return ckpt.pos_min >= pos_min;
    });

if (it != slot.prompt.checkpoints.rend()) {
    // restore the context checkpoint
    it->load_tgt(ctx_tgt, slot.id, LLAMA_STATE_SEQ_FLAGS_NONE);
    // ...
}
```

**Limits:**
| Constraint | Behavior | Location |
|---|---|---|
| Multimodal | **NOT supported** — `do_checkpoint = do_checkpoint && !has_mtmd` | `server-context.cpp:3253` |
| Minimum spacing | `--checkpoint-min-step` tokens between checkpoints | `server-context.cpp:3257` |
